"""Useful, browser-local discovery tools for the public website."""
import hashlib,html,json
from pathlib import Path
ROOT=Path(__file__).parent
TEXT=json.loads((ROOT/'studio.json').read_text())
def esc(s):return html.escape(str(s),quote=True)
def enrich_studio(lang,out,client):
 t=TEXT[lang];e=lambda k:esc(t[k]);br=lambda k:e(k).replace('\n','<br>')
 profiles=''.join(f'<button type="button" data-studio-profile="{i}" aria-pressed="{str(i==0).lower()}">{esc(label)}</button>' for i,label in enumerate(t['profiles']))
 flow=''.join(f'<div class="system-node"><span class="system-number">0{i+1}</span><span class="system-icon" aria-hidden="true">{["↗","◈","⌁"][i]}</span><strong>{esc(label)}</strong><p data-flow-item="{i}">{esc(t["flowitems"][0][i])}</p></div>' for i,label in enumerate(t['flow']))
 out['studio_hero']=f'''<div class="system-canvas"><div class="canvas-top"><span>N / SYSTEM DESIGN</span><span class="canvas-badge">{e('canvas')}</span></div><fieldset class="profile-selector"><legend>{e('choose')}</legend>{profiles}</fieldset><h2 id="system-pain">{esc(t['pains'][0])}</h2><div class="system-flow">{flow}</div><div class="canvas-bottom"><span class="canvas-axis" aria-hidden="true">N — 01 / 03</span><p>{e('canvasnote')}</p><a href="#studio" class="text-link">{e('start')} ↗</a></div></div>'''
 needs=''.join(f'<label class="need-option"><input type="checkbox" data-studio-need="{i}" {"checked" if i in [0,1,3] else ""}><span class="need-number" aria-hidden="true">0{i+1}</span><span><strong>{esc(v)}</strong><small>{esc(t["modulecopy"][i])}</small></span><span class="need-check" aria-hidden="true">+</span></label>' for i,v in enumerate(t['modules']))
 sliders=''.join(f'<label class="estimate-field" for="estimate-{key}"><span>{e(label)}</span><output id="estimate-{key}-value" for="estimate-{key}">{value}{" %" if key=="share" else ""}</output><input id="estimate-{key}" type="range" min="{minimum}" max="{maximum}" step="{step}" value="{value}"></label>' for key,label,minimum,maximum,step,value in [('volume','volume',0,500,1,100),('manual','manual',1,60,1,12),('share','share',0,100,5,60),('review','review',0,30,0.5,2)])
 out['studio_explorer']=f'''<section id="studio" class="solution-studio section shell" aria-labelledby="studio-title"><div class="section-heading"><div><p class="eyebrow">{e('explabel')}</p><h2 id="studio-title">{br('exptitle')}</h2></div><p class="section-copy">{e('expcopy')}</p></div><div class="studio-grid"><div class="studio-choices"><fieldset class="needs-selector"><legend>{e('needs')}</legend>{needs}</fieldset><button type="button" class="text-link studio-reset" id="studio-reset">{e('reset')} ↺</button></div><div class="studio-output"><div class="studio-output-top"><span>N / BLUEPRINT</span><span id="studio-profile-name">{esc(t['profiles'][0])}</span></div><h3>{e('architecture')}</h3><div id="studio-architecture" class="architecture-modules" role="status" aria-live="polite"></div><p class="architecture-base">{e('foundation')}</p><div class="studio-recommendation"><span class="eyebrow">{e('recommend')}</span><p id="studio-recommendation">{esc(t['recommendations'][0])}</p></div><details class="studio-boundaries" open><summary>{e('dependency')}</summary><p id="studio-dependency">{esc(t['dependencies'][0])}</p><p id="studio-integration" hidden>{e('integrations')}</p><p id="studio-ai" hidden><strong>{e('ai')}</strong> {e('aicopy')}</p></details></div></div><div class="estimate-grid"><div><p class="eyebrow">N / VALUE</p><h3>{e('calc')}</h3>{sliders}</div><div class="estimate-result"><div class="estimate-metric"><output id="estimate-hours">8,7</output><span>{e('hours')}</span></div><p id="estimate-status" role="status">{e('positive')}</p><p class="estimate-formula">{e('formula')}</p></div></div><div class="brief-bar"><div><span class="eyebrow">N / TAKEAWAY</span><h3>{e('brief')}</h3><p>{e('briefnote')}</p></div><div class="brief-actions"><button type="button" class="button" id="studio-transfer">{e('transfer')} ↗</button><button type="button" class="button studio-secondary" id="studio-download">{e('download')} ↓</button><p id="studio-status" role="status" aria-live="polite"></p></div></div></section>'''
 inputs=''.join(f'<div class="order-field"><label for="order-{key}">{e(label)}</label><input id="order-{key}" type="{kind}" value="{value}" {attrs}></div>' for key,label,kind,value,attrs in [('reference','reference','text','NOV-DEMO-001','minlength="3" maxlength="40"'),('quantity','quantity','number',2,'min="1" max="100" step="1"'),('price','unit','number','125.00','min="0.01" max="10000" step="0.01"'),('tax','tax','number',21,'min="0" max="100" step="0.01"')])
 steps=''.join(f'<li data-order-step="{i}" aria-current="{str(i==0).lower()}"><span>0{i+1}</span>{esc(label)}</li>' for i,label in enumerate(t['stages']))
 out['studio_proof']=f'''<section id="preuve" class="proof-section section" aria-labelledby="proof-title"><div class="shell proof-grid"><div class="proof-story"><p class="eyebrow">{e('prooflabel')}</p><h2 id="proof-title">{br('prooftitle')}</h2><p class="section-copy">{e('proofcopy')}</p><ol class="order-steps">{steps}</ol><p id="order-status" role="status" aria-live="polite">{e('draft')}</p><p class="proof-note">{e('proofnote')}</p></div><div class="order-demo"><div class="order-top"><span>N / COMMERCE</span><span class="demo-pill">DEMO</span></div><h3>{e('order')}</h3><p class="order-item">{e('item')}</p><div class="order-fields">{inputs}</div><div class="order-total"><span>{e('total')}</span><output id="order-total">302,50 €</output></div><div class="order-actions"><button type="button" class="button" id="order-check">{e('check')} ↗</button><button type="button" class="button" id="order-approve" disabled>{e('approve')} ✓</button><button type="button" class="text-link" id="order-edit" hidden>{e('edit')} ↺</button></div></div></div></section>'''
 out['studio_start']=e('start');out['studio_demo']=e('demo')
 for name,file in [('studio_style_version','studio.css'),('studio_script_version','studio.js')]:out[name]=hashlib.sha256((ROOT/'assets'/file).read_bytes()).hexdigest()[:10]
 client['studio']=t
